1	/**
2	 * Seam tests: orchestrator dispatch + FakeAdapter.
3	 *
4	 * These tests exercise the ABI seam — the boundary between the adapter
5	 * (which produces an ExecutorResult) and the orchestrator's side-effect
6	 * dispatcher (which translates that result into task YAML mutations).
7	 *
8	 * Uses dispatchExecutorResult (extracted from main.ts) so the full
9	 * bootstrap + poll loop does not need to run.
10	 *
11	 * Revised D5: the executor owns impl-PR creation; the orchestrator only
12	 * records the pr_url reported in result.json. No curl/GitHub API calls are
13	 * made by the orchestrator for impl PRs.
14	 *
15	 * FakeAdapter scenarios:
16	 *   1. in_review with pr_url → task in_review, pr.url recorded, no GitHub API call
17	 *   2. in_review without pr_url → task in_review, no pr.url set
18	 *   3. blocked with pr_url → task blocked, pr.url still recorded (draft PR)
19	 *   4. blocked with reason + suggestion → task marked blocked
20	 *   5. failed with executor_crashed reason → task blocked with executor_failed prefix
21	 *   6. failed with result_schema_invalid reason → task blocked with executor_failed prefix
22	 *   7. cost data — in_review with token_usage + cost_usd → run_completed log entry persists cost
23	 *   8. cost data — in_review without token_usage/cost_usd → run_completed log entry has no cost
24	 *   9. cost data — blocked with token_usage + cost_usd → blocked log entry persists cost
25	 */
26	
27	import { describe, it, expect, vi, afterEach } from "vitest";
28	import {
29	  mkdtempSync,
30	  mkdirSync,
31	  writeFileSync,
32	  readFileSync,
33	  rmSync,
34	} from "node:fs";
35	import { tmpdir } from "node:os";
36	import { join } from "node:path";
37	import { execSync, spawnSync } from "node:child_process";
38	import { stringify as yamlStringify, parse as parseYaml } from "yaml";
39	import type { Task } from "../src/types/task.js";
40	import {
41	  createFakeAdapter,
42	  createInReviewAdapter,
43	  createBlockedAdapter,
44	  createFailedAdapter,
45	} from "@workflow/runtime-abi";
46	import type { ExecutorInput } from "@workflow/runtime-abi";
47	import { dispatchExecutorResult } from "../src/side-effects/dispatch.js";
48	
49	// ── Mock git for dispatch side-effects ────────────────────────────────────────
50	
51	vi.mock("node:child_process", async (importOriginal) => {
52	  const actual = await importOriginal<typeof import("node:child_process")>();
53	  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
54	});
55	
56	// ── Fixtures ──────────────────────────────────────────────────────────────────
57	
58	const FEATURE_ID = "seam-test-feature";
59	const TASK_ID = "T1";
60	const TASK_BRANCH = `feature/${FEATURE_ID}-${TASK_ID}`;
61	const TASK_TITLE = "Seam test task";
62	const GIT_AUTHOR_EMAIL = "agent@test.com";
63	const GITHUB_TOKEN = "ghp_test";
64	const TASK_REPO_URL = "git@github.com:myorg/impl-repo.git";
65	const TASK_BASE_BRANCH = "main";
66	
67	const IMPL_PR_URL = "https://github.com/myorg/impl-repo/pull/99";
68	
69	function makeTask(overrides: Partial<Task> = {}): Task {
70	  return {
71	    id: TASK_ID,
72	    title: TASK_TITLE,
73	    repo: "impl-repo",
74	    status: "in_progress",
75	    depends_on: [],
76	    blocked_reason: null,
77	    blocked_context: null,
78	    branch: TASK_BRANCH,
79	    execution: {
80	      actor_type: "agent",
81	      last_updated_by: null,
82	      last_updated_at: null,
83	    },
84	    pr: { url: "", status: "not_created" },
85	    workspace_pr: null,
86	    log: [],
87	    ...overrides,
88	  };
89	}
90	
91	// ── Temp directory helpers ────────────────────────────────────────────────────
92	
93	const tmpDirs: string[] = [];
94	
95	function makeWorkspaceWithTask(task: Task): string {
96	  const dir = mkdtempSync(join(tmpdir(), "seam-dispatch-unit-"));
97	  tmpDirs.push(dir);
98	  const tasksDir = join(dir, "docs", "features", FEATURE_ID, "tasks");
99	  mkdirSync(tasksDir, { recursive: true });
100	  writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
101	  return dir;
102	}
103	
104	function readTask(wsRoot: string): Task {
105	  return parseYaml(
106	    readFileSync(
107	      join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`),
108	      "utf-8",
109	    ),
110	  ) as Task;
111	}
112	
113	function mockGitSuccess(): ReturnType<typeof spawnSync> {
114	  return {
115	    pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined,
116	  } as unknown as ReturnType<typeof spawnSync>;
117	}
118	
119	afterEach(() => {
120	  while (tmpDirs.length) {
121	    const d = tmpDirs.pop()!;
122	    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
123	  }
124	  vi.clearAllMocks();
125	});
126	
127	const stubInput: ExecutorInput = {
128	  taskId: TASK_ID,
129	  featureId: FEATURE_ID,
130	  workspaceId: "test-workspace",
131	  taskRepoUrl: TASK_REPO_URL,
132	  taskRepoBranch: TASK_BRANCH,
133	  taskRepoPath: "/tmp/impl-repo",
134	  briefingPath: "/tmp/briefing.md",
135	  resultPath: "/tmp/result.json",
136	  sshPrivateKey: "",
137	  githubToken: GITHUB_TOKEN,
138	};
139	
140	// ── 1. in_review with pr_url from result ─────────────────────────────────────
141	
142	describe("seam: in_review with pr_url in result", () => {
143	  it("records pr.url from result.pr_url — no GitHub API call made by orchestrator", async () => {
144	    const wsRoot = makeWorkspaceWithTask(makeTask());
145	    const adapter = createFakeAdapter({ terminal_status: "in_review", pr_url: IMPL_PR_URL });
146	
147	    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
148	    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());
149	
150	    const result = await adapter.run(stubInput);
151	    expect(result.terminal_status).toBe("in_review");
152	    expect(result.pr_url).toBe(IMPL_PR_URL);
153	
154	    const events: Record<string, unknown>[] = [];
155	    await dispatchExecutorResult({
156	      result,
157	      workspaceRoot: wsRoot,
158	      featureId: FEATURE_ID,
159	      taskId: TASK_ID,
160	      taskBranch: TASK_BRANCH,
161	      taskTitle: TASK_TITLE,
162	      taskRepoUrl: TASK_REPO_URL,
163	      taskBaseBranch: TASK_BASE_BRANCH,
164	      githubToken: GITHUB_TOKEN,
165	      gitAuthorEmail: GIT_AUTHOR_EMAIL,
166	      emit: (e) => events.push(e),
167	    });
168	
169	    const task = readTask(wsRoot);
170	    expect(task.status).toBe("in_review");
171	    expect(task.pr.url).toBe(IMPL_PR_URL);
172	    expect(task.log.some((e) => e.action === "run_completed")).toBe(true);
173	
174	    // Orchestrator emits impl_pr_recorded — not impl_pr_opened (no GitHub API call)
175	    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(true);
176	    expect(events.some((e) => e.type === "impl_pr_opened")).toBe(false);
177	
178	    // No curl calls — orchestrator does not open impl PRs
179	    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
180	    expect(curlCalls).toHaveLength(0);
181	  });
182	});
183	
184	// ── 2. in_review without pr_url ───────────────────────────────────────────────
185	
186	describe("seam: in_review without pr_url", () => {
187	  it("task is marked in_review with no pr.url when result carries no pr_url", async () => {
188	    const wsRoot = makeWorkspaceWithTask(makeTask());
189	    const adapter = createInReviewAdapter();
190	
191	    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
192	    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());
193	
194	    const result = await adapter.run(stubInput);
195	    expect(result.terminal_status).toBe("in_review");
196	    expect(result.pr_url).toBeUndefined();
197	
198	    const events: Record<string, unknown>[] = [];
199	    await dispatchExecutorResult({
200	      result,
201	      workspaceRoot: wsRoot,
202	      featureId: FEATURE_ID,
203	      taskId: TASK_ID,
204	      taskBranch: TASK_BRANCH,
205	      taskTitle: TASK_TITLE,
206	      taskRepoUrl: TASK_REPO_URL,
207	      taskBaseBranch: TASK_BASE_BRANCH,
208	      githubToken: GITHUB_TOKEN,
209	      gitAuthorEmail: GIT_AUTHOR_EMAIL,
210	      emit: (e) => events.push(e),
211	    });
212	
213	    const task = readTask(wsRoot);
214	    expect(task.status).toBe("in_review");
215	    // No pr_url in result → pr.url stays empty
216	    expect(task.pr.url).toBe("");
217	    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(false);
218	    // No curl calls
219	    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
220	    expect(curlCalls).toHaveLength(0);
221	  });
222	});
223	
224	// ── 3. blocked with pr_url — draft PR documents failed attempt ────────────────
225	
226	describe("seam: blocked with pr_url (draft PR)", () => {
227	  it("records pr.url on blocked task — draft PR documents failed attempt", async () => {
228	    const wsRoot = makeWorkspaceWithTask(makeTask());
229	    const adapter = createFakeAdapter({
230	      terminal_status: "blocked",
231	      blocked_reason: "tests_failed",
232	      pr_url: IMPL_PR_URL,
233	    });
234	
235	    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
236	    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());
237	
238	    const result = await adapter.run(stubInput);
239	    expect(result.terminal_status).toBe("blocked");
240	    expect(result.pr_url).toBe(IMPL_PR_URL);
241	
242	    const events: Record<string, unknown>[] = [];
243	    await dispatchExecutorResult({
244	      result,
245	      workspaceRoot: wsRoot,
246	      featureId: FEATURE_ID,
247	      taskId: TASK_ID,
248	      taskBranch: TASK_BRANCH,
249	      taskTitle: TASK_TITLE,
250	      taskRepoUrl: TASK_REPO_URL,
251	      taskBaseBranch: TASK_BASE_BRANCH,
252	      githubToken: "",
253	      gitAuthorEmail: GIT_AUTHOR_EMAIL,
254	      emit: (e) => events.push(e),
255	    });
256	
257	    const task = readTask(wsRoot);
258	    expect(task.status).toBe("blocked");
259	    expect(task.blocked_reason).toBe("tests_failed");
260	    // pr_url recorded even though task is blocked
261	    expect(task.pr.url).toBe(IMPL_PR_URL);
262	    expect(events.some((e) => e.type === "impl_pr_recorded")).toBe(true);
263	    // No curl calls
264	    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
265	    expect(curlCalls).toHaveLength(0);
266	  });
267	});
268	
269	// ── 4. blocked with reason + suggestion ──────────────────────────────────────
270	
271	describe("seam: blocked with reason + suggestion", () => {
272	  it("FakeAdapter blocked → task status blocked, reason and suggestion written", async () => {
273	    const wsRoot = makeWorkspaceWithTask(makeTask());
274	    const adapter = createBlockedAdapter("missing_tool", "Install node 20.");
275	
276	    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
277	    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());
278	
279	    const result = await adapter.run(stubInput);
280	    expect(result.terminal_status).toBe("blocked");
281	    expect(result.blocked_reason).toBe("missing_tool");
282	
283	    await dispatchExecutorResult({
284	      result,
285	      workspaceRoot: wsRoot,
286	      featureId: FEATURE_ID,
287	      taskId: TASK_ID,
288	      taskBranch: TASK_BRANCH,
289	      taskTitle: TASK_TITLE,
290	      taskRepoUrl: TASK_REPO_URL,
291	      taskBaseBranch: TASK_BASE_BRANCH,
292	      githubToken: "",
293	      gitAuthorEmail: GIT_AUTHOR_EMAIL,
294	      emit: () => {},
295	    });
296	
297	    const task = readTask(wsRoot);
298	    expect(task.status).toBe("blocked");
299	    expect(task.blocked_reason).toBe("missing_tool");
300	    expect(task.blocked_suggestion).toBe("Install node 20.");
301	    expect(task.log.some((e) => e.action === "blocked")).toBe(true);
302	  });
303	});
304	
305	// ── 5. failed → executor_crashed in blocked_reason ───────────────────────────
306	
307	describe("seam: failed — executor_crashed", () => {
308	  it("FakeAdapter failed with executor_crashed → task blocked with executor_failed prefix", async () => {
309	    const wsRoot = makeWorkspaceWithTask(makeTask());
310	    const adapter = createFakeAdapter({
311	      terminal_status: "failed",
312	      blocked_reason: "executor_crashed (exit 1)",
313	    });
314	
315	    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
316	    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());
317	
318	    const result = await adapter.run(stubInput);
319	    expect(result.terminal_status).toBe("failed");
320	
321	    await dispatchExecutorResult({
322	      result,
323	      workspaceRoot: wsRoot,
324	      featureId: FEATURE_ID,
325	      taskId: TASK_ID,
326	      taskBranch: TASK_BRANCH,
327	      taskTitle: TASK_TITLE,
328	      taskRepoUrl: TASK_REPO_URL,
