/**
 * Smoke test: Claude executor entrypoint (runtime/executors/claude/src/index.ts).
 *
 * Drives the compiled executor binary (dist/index.js) directly with a fixture
 * briefing and a stub `claude` binary on PATH. Does NOT invoke a real LLM.
 *
 * The stub `claude` binary is a tiny Node.js script that writes a valid
 * result.json to RESULT_PATH and exits 0.
 *
 * Covers:
 *   1. Executor exits with code 0 on success (result.json written)
 *   2. result.json has the correct shape (terminal_status field)
 *   3. Executor exits 0 when claude writes a "blocked" result
 *   4. Executor exits 0 when impl repo has no toolchain markers
 *
 * Excluded from unit test suite (vitest.unit.config.ts).
 */

import { describe, it, expect, afterAll } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
  existsSync,
  chmodSync,
} from "node:fs";
import { tmpdir, homedir } from "node:os";
import { join, dirname } from "node:path";
import { execSync, spawnSync } from "node:child_process";

const EXECUTOR_BIN = join(
  dirname(new URL(import.meta.url).pathname),
  "..",
  "..",
  "executors",
  "claude",
  "dist",
  "index.js",
);

const GIT_ENV = {
  GIT_AUTHOR_NAME: "Smoke Test",
  GIT_AUTHOR_EMAIL: "smoke@test.com",
  GIT_COMMITTER_NAME: "Smoke Test",
  GIT_COMMITTER_EMAIL: "smoke@test.com",
};

const tmpDirs: string[] = [];

function trackDir(d: string): string {
  tmpDirs.push(d);
  return d;
}

afterAll(() => {
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

/**
 * Create a minimal bare git repo with one empty commit (no toolchain markers).
 * Returns the file:// URL.
 */
function makeMinimalBareRepo(): { url: string; branch: string } {
  const bareDir = trackDir(mkdtempSync(join(tmpdir(), "smoke-bare-")));
  execSync("git -c init.defaultBranch=main init --bare", {
    cwd: bareDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  const workDir = trackDir(mkdtempSync(join(tmpdir(), "smoke-work-")));
  execSync(`git clone "${bareDir}" .`, {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git checkout -b main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  writeFileSync(join(workDir, "README.md"), "# Smoke test impl repo\n", "utf-8");
  execSync("git add README.md", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync('git commit -m "initial"', {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });
  execSync("git push origin main", {
    cwd: workDir,
    env: { ...process.env, ...GIT_ENV },
    stdio: "pipe",
  });

  return { url: `file://${bareDir}`, branch: "main" };
}

/**
 * Create a stub `claude` binary that writes a result to RESULT_PATH and exits 0.
 * Returns the directory containing the stub (add to PATH).
 */
function makeClaudeStub(terminalStatus: "in_review" | "blocked"): string {
  const stubDir = trackDir(mkdtempSync(join(tmpdir(), "claude-stub-")));
  const scriptContent =
    terminalStatus === "in_review"
      ? [
          "#!/usr/bin/env node",
          `const fs = require("node:fs");`,
          `const p = process.env.RESULT_PATH;`,
          `if (p) fs.writeFileSync(p, JSON.stringify({ terminal_status: "in_review", pr_url: "https://github.com/example/repo/pull/1" }));`,
          // Print a stream-json result line so the executor's watcher fires.
          `console.log(JSON.stringify({ type: "result", subtype: "success" }));`,
        ].join("\n")
      : [
          "#!/usr/bin/env node",
          `const fs = require("node:fs");`,
          `const p = process.env.RESULT_PATH;`,
          `if (p) fs.writeFileSync(p, JSON.stringify({ terminal_status: "blocked", blocked_reason: "smoke_test_blocked", blocked_suggestion: "nothing" }));`,
          `console.log(JSON.stringify({ type: "result", subtype: "success" }));`,
        ].join("\n");

  const stubPath = join(stubDir, "claude");
  writeFileSync(stubPath, scriptContent, "utf-8");
  chmodSync(stubPath, 0o755);
  return stubDir;
}

// ── Helper: run executor and return exit code + result ──────────────────────

interface SmokeRunOpts {
  terminalStatus: "in_review" | "blocked";
  implRepoUrl?: string;
  implRepoBranch?: string;
}

function runExecutorSmoke(opts: SmokeRunOpts): {
  exitCode: number | null;
  result: Record<string, unknown> | null;
} {
  const { terminalStatus } = opts;

  const resultDir = trackDir(mkdtempSync(join(tmpdir(), "smoke-result-")));
  const resultPath = join(resultDir, "result.json");

  const briefingDir = trackDir(mkdtempSync(join(tmpdir(), "smoke-briefing-")));
  const briefingPath = join(briefingDir, "briefing.md");
  writeFileSync(briefingPath, "# Smoke test briefing\n\nDo nothing.\n", "utf-8");

  const implRepoPath = trackDir(mkdtempSync(join(tmpdir(), "smoke-impl-")));

  let repoUrl = opts.implRepoUrl;
  let repoBranch = opts.implRepoBranch ?? "main";

  if (!repoUrl) {
    const { url, branch } = makeMinimalBareRepo();
    repoUrl = url;
    repoBranch = branch;
  }

  const stubDir = makeClaudeStub(terminalStatus);

  const env: NodeJS.ProcessEnv = {
    ...process.env,
    PATH: `${stubDir}:${process.env.PATH ?? "/usr/bin:/bin"}`,
    TASK_ID: "T1",
    FEATURE_ID: "smoke-feature",
    WORKSPACE_ID: "smoke-workspace",
    TASK_REPO_URL: repoUrl,
    TASK_REPO_BRANCH: repoBranch,
    TASK_REPO_PATH: implRepoPath,
    BRIEFING_PATH: briefingPath,
    RESULT_PATH: resultPath,
    GITHUB_TOKEN: "",
    // Day-1 extras (optional — set empty to skip)
    WORKSPACE_ROOT: "",
    WORKFLOW_LOCAL_PATH: "",
    MAX_TURNS: "5",
    LOG_SINK_ENABLED: "0",
    CLAUDE_AGENT_RUNTIME: "1",
    // Suppress MCP setup
    MCP_RAG_URL: "",

