1	/** Task lifecycle statuses. */
2	export type TaskStatus =
3	  | "todo"
4	  | "ready"
5	  | "in_progress"
6	  | "blocked"
7	  | "in_review"
8	  | "done"
9	  | "cancelled";
10	
11	/**
12	 * Reasons a task may be blocked. Written to task.yaml when status becomes blocked.
13	 * Well-known values are enumerated; executor-generated reasons are also valid strings.
14	 */
15	export type BlockedReason =
16	  | "budget_exceeded"
17	  | "iteration_cap_exceeded"
18	  | "no_progress"
19	  | "model_escalation_requested"
20	  | "skill_missing"
21	  | "runtime_error"
22	  | "pr_conflict"
23	  | (string & Record<never, never>);
24	
25	/** Who may execute a task. */
26	export type ActorType = "human" | "agent" | "either";
27	
28	/**
29	 * Tracks the mergeability lifecycle of a task's implementation PR.
30	 * Written to `conflict_state` on the task YAML when the polling loop detects
31	 * a conflict or when the rebase handler updates resolution progress.
32	 */
33	export type ConflictState = "none" | "conflicted" | "resolving" | "resolved";
34	
35	/** One entry in the append-only rebase audit log stored on the task. */
36	export interface RebaseLogEntry {
37	  /** ISO-8601 timestamp when this entry was written. */
38	  at: string;
39	  /** What the rebase handler did or observed at this point. */
40	  action: "rebase_started" | "rebase_completed" | "rebase_blocked" | "rebase_resolved_by_agent";
41	  /** Agent email or actor identifier that wrote this entry. */
42	  by: string;
43	  /** Human-readable detail — e.g. file:line pointers for conflicted hunks. */
44	  note?: string;
45	}
46	
47	/** Pull-request lifecycle state. */
48	export type PrStatus = "not_created" | "open" | "merged" | "closed";
49	
50	/** One entry in the task's append-only audit log. */
51	export interface TaskLogEntry {
52	  action: string;
53	  by: string;
54	  at: string;
55	  note?: string;
56	  [key: string]: unknown;
57	}
58	
59	/** Execution metadata stored on the task. */
60	export interface TaskExecution {
61	  actor_type: ActorType;
62	  last_updated_by: string | null;
63	  last_updated_at: string | null;
64	  /** Written by the agent when blocking; a short human-readable triage hint. */
65	  suggested_next_step?: string | null;
66	}
67	
68	/** Pull-request reference stored on the task. */
69	export interface TaskPr {
70	  url: string;
71	  status: PrStatus;
72	}
73	
74	/**
75	 * Written by the orchestrator (or agent) when a task transitions to `blocked`.
76	 * Captures the exact WIP state so a recovery agent can resume from the same
77	 * branch and SHA rather than starting from scratch.
78	 */
79	export interface BlockedContext {
80	  /** Branch name carrying the WIP commits (e.g. `feature/my-feature-T3`). */
81	  wip_branch: string;
82	  /** HEAD SHA at the time the block was recorded. */
83	  wip_sha: string;
84	  /** ISO-8601 timestamp with timezone when the branch was last pushed. */
85	  pushed_at: string;
86	}
87	
88	/** Full task state as stored in tasks/T<n>.yaml. */
89	export interface Task {
90	  id: string;
91	  title: string;
92	  repo: string;
93	  status: TaskStatus;
94	  depends_on: string[];
95	  blocked_reason: BlockedReason | null;
96	  /** Human-readable hint for the next agent on how to resolve the block. */
97	  blocked_suggestion?: string | null;
98	  /** Structured context for blocked_reason (e.g. current_model for escalation). */
99	  blocked_details?: string | Record<string, unknown> | null;
100	  /**
101	   * WIP branch/SHA snapshot written when the task is blocked.
102	   * Null when the task has never been blocked, or after a successful completion.
103	   */
104	  blocked_context: BlockedContext | null;
105	  branch: string;
106	  execution: TaskExecution;
107	  /**
108	   * Broker handle written at submit time for crash-recovery reconciliation.
109	   * Null until the first executor submit; cleared on completion.
110	   */
111	  execution_handle?: string | null;
112	  /** Implementation-repo PR (opened by the agent after work is complete). */
113	  pr: TaskPr;
114	  /**
115	   * Management-repo PR opened at claim time (feature branch → main).
116	   * Null until the claim commit is pushed and the PR is created.
117	   */
118	  workspace_pr: TaskPr | null;
